CREATE SCHEMA IF NOT EXISTS master;

-- PROGRAM MASTER
CREATE TABLE IF NOT EXISTS master.program_master (
    program_id        VARCHAR(10)     PRIMARY KEY,
    program_name      VARCHAR(100)    NOT NULL,
    created_at        TIMESTAMP       DEFAULT CURRENT_TIMESTAMP
);

-- DEVICE MASTER
CREATE TABLE IF NOT EXISTS master.device_master (
    device_id        VARCHAR(50)     PRIMARY KEY,
    device_name      VARCHAR(100)    NOT NULL,
    device_type      VARCHAR(50)     NOT NULL,
    created_at       TIMESTAMP       DEFAULT CURRENT_TIMESTAMP
);

-- ANALYST USERS
CREATE TABLE IF NOT EXISTS master.analyst_users (
    analyst_id      VARCHAR(20)     PRIMARY KEY,
    employee_name   VARCHAR(100)    NOT NULL,
    username        VARCHAR(50)     UNIQUE NOT NULL,
    password        VARCHAR(255)    NOT NULL,
    role            VARCHAR(50)     NOT NULL,
    -- Notification email for backlog / alert digests (nullable for legacy rows).
    email           VARCHAR(255),
    created_at      TIMESTAMP       DEFAULT CURRENT_TIMESTAMP
);

-- RULE MASTER
CREATE TYPE time_interval_unit AS ENUM (
    'MINUTE',
    'HOUR',
    'DAY'
);

CREATE TABLE IF NOT EXISTS master.rule_master (
    rule_id VARCHAR(10) PRIMARY KEY,
    rule_name VARCHAR(100) NOT NULL,
    rule_description TEXT,
    rule_type VARCHAR(20) NOT NULL,
    action VARCHAR(20) NOT NULL,
    threshold_value NUMERIC(10,2),
    time_interval_value INT,
    time_interval_unit time_interval_unit,
    -- Review timeout (minutes) before an order may be auto-approved.
    -- Source of truth for fraud-engine hold / backlog / scheduler logic.
    -- Default 60 for all rules; R001 (P2 iPhone) is seeded as 180.
    delay_minutes INT NOT NULL DEFAULT 60,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT chk_time_interval
        CHECK (
            (time_interval_value IS NULL AND time_interval_unit IS NULL) OR
            (time_interval_value IS NOT NULL AND time_interval_unit IS NOT NULL)
        ),
    CONSTRAINT chk_delay_minutes_positive
        CHECK (delay_minutes > 0)
);

-- PRODUCTS
CREATE TABLE IF NOT EXISTS master.products (
    product_id        VARCHAR(20)     PRIMARY KEY,
    product_name      VARCHAR(150)    NOT NULL,
    category          VARCHAR(100)    NOT NULL,
    price             NUMERIC(12,2)   NOT NULL,
    created_at        TIMESTAMP       DEFAULT CURRENT_TIMESTAMP
);

-- IP BLACKLIST
CREATE TABLE IF NOT EXISTS master.ip_blacklist (
    blacklist_id     SERIAL          PRIMARY KEY,
    ip_address       VARCHAR(50)     NOT NULL,
    reason           TEXT            NOT NULL,
    is_active        BOOLEAN         NOT NULL DEFAULT TRUE,
    blacklisted_by   VARCHAR(20)     REFERENCES master.analyst_users(analyst_id),
    blacklisted_at   TIMESTAMP       DEFAULT CURRENT_TIMESTAMP,
    removed_by       VARCHAR(20)     REFERENCES master.analyst_users(analyst_id),
    removed_at       TIMESTAMP
);

CREATE TABLE master.phone_blacklist (
    blacklist_id SERIAL PRIMARY KEY,
    phone_number VARCHAR(20) NOT NULL UNIQUE,
    reason TEXT NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    blacklisted_by VARCHAR(100),
    blacklisted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    removed_by VARCHAR(100),
    removed_at TIMESTAMP
);

CREATE TABLE master.email_blacklist (
    blacklist_id SERIAL PRIMARY KEY,
    email VARCHAR(255) NOT NULL UNIQUE,
    reason TEXT NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    blacklisted_by VARCHAR(100),
    blacklisted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    removed_by VARCHAR(100),
    removed_at TIMESTAMP
);

-- ANALYST PERMISSIONS
CREATE TABLE IF NOT EXISTS master.analyst_permissions (
    analyst_id   VARCHAR(20) NOT NULL REFERENCES master.analyst_users(analyst_id),
    page_key     VARCHAR(50) NOT NULL CHECK (page_key IN ('FRAUD_DASHBOARD', 'ADMIN_PANEL', 'POWER_BI_DASHBOARD', 'AI_CHATBOT')),
    granted      BOOLEAN NOT NULL DEFAULT TRUE,
    granted_by   VARCHAR(20) REFERENCES master.analyst_users(analyst_id),
    granted_at   TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (analyst_id, page_key)
);

-- CUSTOMERS
CREATE TABLE IF NOT EXISTS master.customers (
    user_id           VARCHAR(20)     PRIMARY KEY,
    customer_name     VARCHAR(100)    NOT NULL,
    email             VARCHAR(100)    NOT NULL,
    phone_number      VARCHAR(20),
    default_address   TEXT,
    street            VARCHAR(255),
    city              VARCHAR(100),
    state             VARCHAR(100),
    country           VARCHAR(100)    DEFAULT 'India',
    zip_code          VARCHAR(20),
    program_id        VARCHAR(10)     REFERENCES master.program_master(program_id),
    created_at        TIMESTAMP       DEFAULT CURRENT_TIMESTAMP,
    password          VARCHAR(255)
);

-- ORDERS
CREATE TABLE IF NOT EXISTS master.orders (
    order_id          VARCHAR(20)    PRIMARY KEY,
    user_id           VARCHAR(20)    NOT NULL REFERENCES master.customers(user_id),
    customer_name     VARCHAR(100),
    email             VARCHAR(100),
    phone_number      VARCHAR(20),
    address           TEXT,
    street            VARCHAR(255),
    city              VARCHAR(100),
    state             VARCHAR(100),
    country           VARCHAR(100)   DEFAULT 'India',
    zip_code          VARCHAR(20),
    program_id        VARCHAR(10)    REFERENCES master.program_master(program_id),
    product_id        VARCHAR(20)    REFERENCES master.products(product_id),
    category          VARCHAR(100),
    product_name      VARCHAR(150),
    quantity          INT            DEFAULT 1,
    amount            NUMERIC(12,2)  NOT NULL,
    order_timestamp   TIMESTAMP      NOT NULL,
    order_status      VARCHAR(30)    DEFAULT 'APPROVED' CHECK (order_status IN ('APPROVED', 'PENDING_REVIEW', 'ON_HOLD', 'REJECTED')),
    order_approved_at TIMESTAMP,
    order_rejected_at TIMESTAMP,
    delay_minutes     INT            DEFAULT 0,
    ip_address        VARCHAR(50),
    device_id         VARCHAR(50)    REFERENCES master.device_master(device_id),
    is_fraud          BOOLEAN        DEFAULT FALSE,
    flagged_reason    TEXT,
    reviewed_by       VARCHAR(20)    REFERENCES master.analyst_users(analyst_id),
    review_comments   TEXT
);

-- Order Rule Hit
CREATE TABLE IF NOT EXISTS master.order_rule_hits (
    hit_id BIGSERIAL PRIMARY KEY,
    order_id VARCHAR(20) NOT NULL REFERENCES master.orders(order_id) ON DELETE CASCADE,
    rule_id VARCHAR(10) NOT NULL,
    rule_name VARCHAR(100) NOT NULL,
    rule_description TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Append-only audit trail for analyst and system review actions
CREATE TABLE IF NOT EXISTS master.order_review_audit (
    audit_id          BIGSERIAL PRIMARY KEY,
    order_id          VARCHAR(20) NOT NULL REFERENCES master.orders(order_id) ON DELETE CASCADE,
    analyst_id        VARCHAR(20),
    action            VARCHAR(30) NOT NULL,
    rule_name         TEXT,
    delay_minutes     INT,
    reason            VARCHAR(30) NOT NULL DEFAULT 'Manual',
    review_comments   TEXT,
    created_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Backlog / queue query support
CREATE INDEX IF NOT EXISTS idx_orders_status_timestamp
    ON master.orders (order_status, order_timestamp)
    WHERE order_status IN ('ON_HOLD', 'PENDING_REVIEW');

CREATE INDEX IF NOT EXISTS idx_order_rule_hits_order_id
    ON master.order_rule_hits (order_id);

CREATE INDEX IF NOT EXISTS idx_order_review_audit_order_id
    ON master.order_review_audit (order_id, created_at DESC);

CREATE TABLE IF NOT EXISTS master.ai_chat_logs (
    chat_log_id BIGSERIAL PRIMARY KEY,
    prompt TEXT NOT NULL,
    generated_sql TEXT,
    result_table JSONB,
    generated_summary TEXT,
    input_tokens INTEGER NOT NULL DEFAULT 0,
    output_tokens INTEGER NOT NULL DEFAULT 0,
    total_tokens INTEGER GENERATED ALWAYS AS (input_tokens + output_tokens) STORED,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);


--=====================================================================
-- SEED DATA
--======================================================================
ON CONFLICT (program_id) DO NOTHING;

ON CONFLICT (device_id) DO NOTHING;

ON CONFLICT (username) DO NOTHING;

ON CONFLICT (analyst_id, page_key) DO NOTHING;

    -- R001 uses delay_minutes (180) for review timeout; time_interval is unused for this static rule
    ('R001', 'P2 iPhone 16 Rule', 'iPhone 16 order from P2 track with delay', 'STATIC', 'HOLD', NULL, NULL, NULL, 180, '2026-07-05 17:14:40.155171'),
    ('R002', 'Email Velocity', 'More than 3 orders from same email', 'VELOCITY', 'REVIEW', '3.00', '30', 'MINUTE', 60, '2026-07-05 17:14:40.155171'),
    ('R003', 'IP Velocity', 'More than 5 orders from same IP', 'VELOCITY', 'REVIEW', '5.00', '1', 'HOUR', 60, '2026-07-05 17:14:40.155171'),
    ('R004', 'Device Velocity', 'More than 4 orders from same device', 'VELOCITY', 'REVIEW', '4.00', '1', 'HOUR', 60, '2026-07-05 17:14:40.155171'),
    ('R005', 'User Spend Velocity', 'User spend exceeds threshold', 'VELOCITY', 'REVIEW', '200000.00', '24', 'HOUR', 60, '2026-07-05 17:14:40.155171'),
    ('R006', 'Multiple Users Same Email', 'Same email used by multiple user IDs', 'LINKAGE', 'REVIEW', '1.00', NULL, NULL, 60, '2026-07-05 17:14:40.155171'),
    ('R007', 'Blacklisted IP', 'IP found in blacklist', 'STATIC', 'REJECTED', '0.00', NULL, NULL, 60, '2026-07-05 17:14:40.155171'),
    ('R008', 'Burst Orders', 'Three or more orders', 'VELOCITY', 'REVIEW', '3.00', '5', 'MINUTE', 60, '2026-07-05 17:14:40.155171'),
    ('R009', 'Address Velocity', 'More than five orders to same address', 'VELOCITY', 'REVIEW', '5.00', '24', 'HOUR', 60, '2026-07-05 17:14:40.155171'),
    ('R010', 'Device Switching', 'Same user switches devices', 'BEHAVIORAL', 'REVIEW', '2.00', '30', 'MINUTE', 60, '2026-07-05 17:14:40.155171'),
    ('R011', 'Blacklisted Phone Number', 'Phone number found in blacklist', 'STATIC', 'REJECTED', '0.00', NULL, NULL, 60, '2026-07-05 17:14:40.155171'),
    ('R012', 'Blacklisted Email', 'Email found in blacklist', 'STATIC', 'REJECTED', '0.00', NULL, NULL, 60, '2026-07-05 17:14:40.155171')
ON CONFLICT (rule_id) DO UPDATE SET
    rule_description = EXCLUDED.rule_description,
    threshold_value = EXCLUDED.threshold_value,
    time_interval_value = EXCLUDED.time_interval_value,
    time_interval_unit = EXCLUDED.time_interval_unit,
    delay_minutes = EXCLUDED.delay_minutes;

ON CONFLICT (product_id) DO UPDATE SET product_name = EXCLUDED.product_name, category = EXCLUDED.category, price = EXCLUDED.price;




ON CONFLICT (user_id) DO NOTHING;

ON CONFLICT (order_id) DO NOTHING;

CREATE SEQUENCE IF NOT EXISTS master.order_id_seq START 15001;

ALTER TABLE master.orders 
ALTER COLUMN order_id 
SET DEFAULT 'ORD-' || LPAD(nextval('master.order_id_seq')::text, 6, '0');

ON CONFLICT (hit_id) DO NOTHING;

SELECT setval(
    pg_get_serial_sequence('master.order_rule_hits', 'hit_id'),
    COALESCE((SELECT MAX(hit_id) FROM master.order_rule_hits), 1)
);
